  ('1684bb2d-0469-4e21-a1e7-0deb2295e843', 'social-media', 'share', 282, 'إدارة السوشيال ميديا', 'Social Media Management', 'حضور يومي مدروس يبني مجتمع حوالين البراند بتاعك.', 'A consistent, strategic presence that builds community.', 'خطة محتوى شهرية، تصميمات، كتابة، نشر، ورد على الجمهور — بندير صفحاتك كأنها صفحاتنا وبنقيس كل حاجة.', 'Monthly content plans, design, copy, publishing and community management — we run your pages like our own and measure everything.', '[{"ar":"خطة محتوى","en":"Content plan"},{"ar":"إدارة مجتمع","en":"Community"},{"ar":"تقارير","en":"Reporting"}]'::jsonb, '[{"title_ar":"خطة محتوى شهرية","title_en":"Monthly content plan","text_ar":"أفكار وتواريخ وأهداف لكل بوست.","text_en":"Ideas, dates and goals for every post."},{"title_ar":"تصميم وكتابة","title_en":"Design & copy","text_ar":"بوستات وستوريز وريلز بهوية ثابتة.","text_en":"Posts, stories and reels on-brand."},{"title_ar":"إدارة التعليقات والرسائل","title_en":"Community management","text_ar":"رد سريع ومحترف على جمهورك.","text_en":"Fast, professional replies to your audience."},{"title_ar":"تقرير شهري","title_en":"Monthly report","text_ar":"أرقام واضحة وتوصيات للشهر الجاي.","text_en":"Clear numbers and next-month recommendations."}]'::jsonb, '[{"title_ar":"اكتشاف","title_en":"Discover","text_ar":"نفهم البيزنس والسوق والجمهور قبل أي خطوة.","text_en":"We learn your business, market and audience before anything else."},{"title_ar":"تخطيط","title_en":"Plan","text_ar":"نحوّل اللي فهمناه لاستراتيجية واضحة بأهداف قابلة للقياس.","text_en":"We turn insight into a clear strategy with measurable goals."},{"title_ar":"تنفيذ","title_en":"Create","text_ar":"فريقنا ينفذ بجودة عالية وفي المواعيد المتفق عليها.","text_en":"Our team executes with craft, on schedule."},{"title_ar":"قياس وتطوير","title_en":"Measure & grow","text_ar":"نتابع الأرقام ونحسّن باستمرار عشان النتيجة تكبر.","text_en":"We track the numbers and keep optimising so results compound."}]'::jsonb, '[{"q_ar":"بتديروا أنهي منصات؟","q_en":"Which platforms do you manage?","a_ar":"فيسبوك، إنستجرام، تيك توك، لينكدإن وغيرهم حسب جمهورك.","a_en":"Facebook, Instagram, TikTok, LinkedIn and more — wherever your audience is."},{"q_ar":"كام بوست في الشهر؟","q_en":"How many posts per month?","a_ar":"حسب الباقة، من ١٢ لـ ٣٠ بوست بالإضافة للستوريز.","a_en":"Depending on the package, 12–30 posts plus stories."},{"q_ar":"هل الإعلانات ضمن الإدارة؟","q_en":"Are ads included?","a_ar":"الإعلانات خدمة منفصلة ويمكن دمجها في باقة واحدة.","a_en":"Ads are a separate service and can be bundled."}]'::jsonb, 1),
  ('79672a31-7599-4bd7-a333-3bc8438ce91a', 'content-creation', 'pen', 255, 'صناعة المحتوى', 'Content Creation', 'محتوى يتقري ويتشير — مكتوب ومرئي بلغة جمهورك.', 'Content people read and share — written and visual, in your audience''s language.', 'كتابة إعلانية، سكريبتات فيديو، مقالات، وأفكار ريلز — محتوى مبني على فهم الجمهور ومصمم عشان يحرك أرقام حقيقية.', 'Copywriting, video scripts, articles and reel concepts — content grounded in audience insight and built to move real numbers.', '[{"ar":"كوبي رايتنج","en":"Copywriting"},{"ar":"سكريبتات","en":"Scripts"},{"ar":"ريلز","en":"Reels"}]'::jsonb, '[{"title_ar":"كتابة إعلانية","title_en":"Ad copy","text_ar":"نصوص بتقنع وبتبيع.","text_en":"Copy that persuades and converts."},{"title_ar":"سكريبتات فيديو","title_en":"Video scripts","text_ar":"قصص قصيرة بتشد من أول ثانية.","text_en":"Short stories that hook from second one."},{"title_ar":"محتوى المواقع","title_en":"Web copy","text_ar":"صفحات واضحة ومهيأة لمحركات البحث.","text_en":"Clear, SEO-ready pages."},{"title_ar":"أفكار حملات","title_en":"Campaign concepts","text_ar":"أفكار كبيرة قابلة للتنفيذ.","text_en":"Big ideas that can actually ship."}]'::jsonb, '[{"title_ar":"اكتشاف","title_en":"Discover","text_ar":"نفهم البيزنس والسوق والجمهور قبل أي خطوة.","text_en":"We learn your business, market and audience before anything else."},{"title_ar":"تخطيط","title_en":"Plan","text_ar":"نحوّل اللي فهمناه لاستراتيجية واضحة بأهداف قابلة للقياس.","text_en":"We turn insight into a clear strategy with measurable goals."},{"title_ar":"تنفيذ","title_en":"Create","text_ar":"فريقنا ينفذ بجودة عالية وفي المواعيد المتفق عليها.","text_en":"Our team executes with craft, on schedule."},{"title_ar":"قياس وتطوير","title_en":"Measure & grow","text_ar":"نتابع الأرقام ونحسّن باستمرار عشان النتيجة تكبر.","text_en":"We track the numbers and keep optimising so results compound."}]'::jsonb, '[{"q_ar":"بتكتبوا بالعامية ولا الفصحى؟","q_en":"Do you write in Egyptian Arabic or MSA?","a_ar":"الاتنين، حسب جمهور