  ('29d5f6d7-1c45-4df1-a49b-b59eccf70177', 'web-development', 'code', 250, 'تصميم وتطوير المواقع', 'Web Design & Development', 'مواقع سريعة وجميلة بتحوّل الزوار لعملاء.', 'Fast, beautiful websites that turn visitors into customers.', 'مواقع تعريفية ومتاجر إلكترونية بتصميم مخصص، أداء عالي، ولوحة تحكم سهلة — مبنية بأحدث التقنيات.', 'Corporate sites and e-commerce stores with custom design, top performance and an easy admin — built on modern tech.', '[{"ar":"مواقع تعريفية","en":"Websites"},{"ar":"متاجر","en":"E-commerce"},{"ar":"UI/UX","en":"UI/UX"}]'::jsonb, '[{"title_ar":"تصميم UI/UX","title_en":"UI/UX design","text_ar":"تجربة استخدام واضحة وجذابة.","text_en":"Clear, engaging user experience."},{"title_ar":"تطوير","title_en":"Development","text_ar":"كود نظيف وسريع ومتجاوب.","text_en":"Clean, fast, responsive code."},{"title_ar":"لوحة تحكم","title_en":"Admin panel","text_ar":"تعديل المحتوى بنفسك بسهولة.","text_en":"Edit your content yourself, easily."},{"title_ar":"استضافة ودعم","title_en":"Hosting & support","text_ar":"إطلاق ومتابعة بعد التسليم.","text_en":"Launch and ongoing care."}]'::jsonb, '[{"title_ar":"اكتشاف","title_en":"Discover","text_ar":"نفهم البيزنس والسوق والجمهور قبل أي خطوة.","text_en":"We learn your business, market and audience before anything else."},{"title_ar":"تخطيط","title_en":"Plan","text_ar":"نحوّل اللي فهمناه لاستراتيجية واضحة بأهداف قابلة للقياس.","text_en":"We turn insight into a clear strategy with measurable goals."},{"title_ar":"تنفيذ","title_en":"Create","text_ar":"فريقنا ينفذ بجودة عالية وفي المواعيد المتفق عليها.","text_en":"Our team executes with craft, on schedule."},{"title_ar":"قياس وتطوير","title_en":"Measure & grow","text_ar":"نتابع الأرقام ونحسّن باستمرار عشان النتيجة تكبر.","text_en":"We track the numbers and keep optimising so results compound."}]'::jsonb, '[{"q_ar":"الموقع بياخد وقت قد إيه؟","q_en":"How long does a website take?","a_ar":"من ٣ لـ ٨ أسابيع حسب عدد الصفحات والمميزات.","a_en":"3–8 weeks depending on pages and features."},{"q_ar":"الموقع هيبقى عربي وإنجليزي؟","q_en":"Will it be bilingual?","a_ar":"أيوه، بنبني مواقع ثنائية اللغة بالكامل.","a_en":"Yes — fully bilingual builds are our default."},{"q_ar":"أقدر أعدل المحتوى بنفسي؟","q_en":"Can I edit content myself?","a_ar":"أكيد، من لوحة تحكم بسيطة.","a_en":"Of course, from a simple admin panel."}]'::jsonb, 6),
  ('4a7fcc79-3d9c-4d7a-aae4-5cfdd5131cc6', 'seo', 'search', 286, 'تحسين محركات البحث SEO', 'SEO', 'تظهر في أول نتايج جوجل لما عميلك يدور عليك.', 'Show up first on Google when customers search for you.', 'تحسين تقني ومحتوى وروابط — خطة SEO طويلة المدى بتجيب زيارات مجانية ومستمرة من عملاء بيدوروا على خدمتك.', 'Technical, content and link SEO — a long-term plan that brings free, compounding traffic from people searching for what you sell.', '[{"ar":"SEO تقني","en":"Technical SEO"},{"ar":"كلمات مفتاحية","en":"Keywords"},{"ar":"SEO محلي","en":"Local SEO"}]'::jsonb, '[{"title_ar":"تدقيق تقني","title_en":"Technical audit","text_ar":"إصلاح كل اللي بيعطل ظهورك.","text_en":"Fix everything holding rankings back."},{"title_ar":"بحث كلمات","title_en":"Keyword research","text_ar":"الكلمات اللي عملاءك بيدوروا بيها.","text_en":"The words your customers actually search."},{"title_ar":"محتوى محسّن","title_en":"Optimised content","text_ar":"صفحات ومقالات بتتصدر.","text_en":"Pages and articles that rank."},{"title_ar":"SEO محلي","title_en":"Local SEO","text_ar":"ظهور على خرايط جوجل في مدينتك.","text_en":"Visibility on Google Maps in your city."}]'::jsonb, '[{"title_ar":"اكتشاف","title_en":"Discover","text_ar":"نفهم البيزنس والسوق والجمهور قبل أي خطوة.","text_en":"We learn your business, market and audience before anything else."},{"title_ar":"تخطيط","title_en":"Plan","text_ar":"نحوّل اللي فهمناه لاستراتيجية واضحة بأهداف قابلة للقياس.","text_en":"We turn insight into a clear strategy with measurable goals."},{"title_ar":"تنفيذ","title_en":"Create","text_ar":"فريقنا ينفذ بجودة عالية وفي المواعيد المتفق عليها.","text_en":"Our team executes with craft, on schedule."},{"title_ar":"قياس وتطوير","title_en":"Measure & grow","text_ar":"نتابع الأرقام ونحسّن باستمرار عشان النتيجة تكبر.","text_en":"We track the numbers and keep optimising so results compound."}]'::jsonb, '[{"q_ar":"إمتى النتايج تبان؟","q_en":"When do results show?","a_ar":"غالباً من ٣ لـ ٦ شهور للنتايج القوية.","a_en":"Usually 3–6 months for strong results."},{"q_ar":"بتضمنوا المركز الأول؟","q_en":"Do you guarantee #1?","a_ar":"محدش يقدر يضمن ده بأمانة، لكن بنضمن شغل منهجي وتقارير شفافة.","a_en":"No one honestly can — we guarantee methodical work and transparent reporting."},{"q_ar":"محتاج أكتب مقالات؟","q_en":"Do I need to blog?","a_ar":"إحنا بنكتب المحتوى المطلوب ضمن الخطة.","a_en":"We write the content as part of the plan."}]'::jsonb, 7)
