  ('49aa62fc-e895-4a08-aa11-471107365dd4', 'nile-roastery', 'محمصة النيل', 'Nile Roastery', 'مشروع تجريبي (Placeholder)', 'Placeholder project', '1b6b55ec-0278-4dbc-a25a-ff325bc85804', 2025, array['branding','photo-video-production']::text[], 'هوية بصرية كاملة لمحمصة قهوة محلية بتتوسع.', 'A full identity for a growing local coffee roastery.', 'براند محلي محتاج يبان premium وينافس السلاسل الكبيرة.', 'A local brand needing to feel premium and compete with big chains.', 'هوية مستوحاة من النيل، تغليف مميز، وتصوير منتجات دافي.', 'A Nile-inspired identity, distinctive packaging and warm product photography.', '[{"value":140,"suffix":"%","label_ar":"زيادة المبيعات","label_en":"Sales increase"},{"value":3,"suffix":"x","label_ar":"تفاعل السوشيال","label_en":"Social engagement"},{"value":2,"suffix":"","label_ar":"فروع جديدة","label_en":"New branches"}]'::jsonb, 268, true, true, 0),
  ('4c03a1dd-f587-403e-ae6a-98693ea5056f', 'pulse-fitness', 'بلس فيتنس', 'Pulse Fitness', 'مشروع تجريبي (Placeholder)', 'Placeholder project', 'b7275262-1db1-436a-ac83-ab63b7fe8082', 2025, array['media-buying','performance-marketing']::text[], 'حملة اشتراكات لسلسلة جيمات.', 'A membership campaign for a gym chain.', 'تكلفة العميل عالية وموسم الصيف قرب.', 'High cost per lead with summer season approaching.', 'قمع مبيعات جديد، إعلانات فيديو قصيرة، واستهداف حسب المنطقة.', 'A new funnel, short-form video ads and geo-targeting.', '[{"value":62,"suffix":"%","label_ar":"انخفاض تكلفة العميل","label_en":"Lower cost per lead"},{"value":1800,"suffix":"+","label_ar":"اشتراك جديد","label_en":"New members"},{"value":5,"suffix":"x","label_ar":"عائد الإعلانات","label_en":"ROAS"}]'::jsonb, 290, true, true, 1),
  ('e9211ad3-dfe7-4c3e-af9d-d5b765aaf96f', 'saha-clinics', 'عيادات صحة', 'Saha Clinics', 'مشروع تجريبي (Placeholder)', 'Placeholder project', '6e26c975-c0bd-4a39-ab91-4cb9b950bc00', 2024, array['web-development','seo']::text[], 'موقع حجز ثنائي اللغة لمجموعة عيادات.', 'A bilingual booking site for a clinic group.', 'الحجوزات كلها بالتليفون وضغط كبير على الاستقبال.', 'All bookings by phone, overwhelming reception.', 'موقع سريع بنظام حجز أونلاين وSEO محلي لكل فرع.', 'A fast site with online booking and local SEO per branch.', '[{"value":70,"suffix":"%","label_ar":"حجوزات أونلاين","label_en":"Online bookings"},{"value":4,"suffix":"x","label_ar":"زيارات من جوجل","label_en":"Google traffic"},{"value":98,"suffix":"","label_ar":"تقييم الأداء","label_en":"Performance score"}]'::jsonb, 252, true, true, 2),
  ('c3ea8238-beec-4b65-ad8a-c2789eb1cba2', 'dahab-jewelry', 'ذهب للمجوهرات', 'Dahab Jewelry', 'مشروع تجريبي (Placeholder)', 'Placeholder project', 'e98d0088-8a8b-4d6c-ab52-4f5c753d95ff', 2024, array['photo-video-production','social-media']::text[], 'تصوير وفيديوهات لكولكشن جديد.', 'Photo and film for a new collection launch.', 'إطلاق كولكشن في وقت قصير جداً.', 'Launching a collection on a very tight timeline.', 'يوم تصوير سينمائي وسلسلة ريلز للإطلاق.', 'A cinematic shoot day and a launch reel series.', '[{"value":2.4,"suffix":"M","label_ar":"مشاهدة","label_en":"Views"},{"value":85,"suffix":"%","label_ar":"نفاد الكولكشن","label_en":"Collection sold"},{"value":12,"suffix":"K","label_ar":"متابع جديد","label_en":"New followers"}]'::jsonb, 300, true, true, 3),
  ('3961b6c3-2d4e-44a9-a48b-6bd0d3be5934', 'baladi-bakery', 'مخبز بلدي', 'Baladi Bakery', 'مشروع تجريبي (Placeholder)', 'Placeholder project', '23e54aaa-4215-4143-aa56-b53dfa8d2789', 2024, array['social-media','content-creation']::text[], 'إدارة سوشيال ميديا لمخبز عائلي.', 'Social media management for a family bakery.', 'صفحة خاملة وجمهور مش متفاعل.', 'A dormant page with an unengaged audience.', 'محتوى يومي بيحكي قصة العيلة والمنتج الطازة.', 'Daily content telling the family story and fresh-baked craft.', '[{"value":320,"suffix":"%","label_ar":"نمو التفاعل","label_en":"Engagement growth"},{"value":25,"suffix":"K","label_ar":"متابع","label_en":"Followers"},{"value":40,"suffix":"%","label_ar":"طلبات أونلاين","label_en":"Online orders"}]'::jsonb, 275, true, true, 4),
  ('42cc023b-8663-410b-abcc-15720c00ebd5', 'tamar-realestate', 'تمار العقارية', 'Tamar Real Estate', 'مشروع تجريبي (Placeholder)', 'Placeholder project', '1b6b55ec-0278-4dbc-a25a-ff325bc85804', 2023, array['branding','web-development']::text[], 'إعادة بناء هوية شركة تطوير عقاري.', 'A rebrand for a real-estate developer.', 'هوية قديمة مش بتعكس حجم المشاريع.', 'An outdated identity that undersold their projects.', 'هوية معمارية حديثة وموقع لعرض الوحدات.', 'A modern architectural identity and a units showcase site.', '[{"value":2,"suffix":"x","label_ar":"استفسارات","label_en":"Enquiries"},{"value":45,"suffix":"%","label_ar":"مدة أطول في الموقع","label_en":"Longer sessions"},{"value":1,"suffix":"","label_ar":"هوية موحدة","label_en":"Unified identity"}]'::jsonb, 258, false, true, 5)
insert into public.testimonials (id, name_ar, name_en, role_ar, role_en, company_ar, company_en, quote_ar, quote_en, rating, is_placeholder, sort_order) values
  ('63a4f368-1eac-4b14-a9b6-e1385702ccc5', 'أحمد سمير', 'Ahmed Samir', 'المدير التنفيذي', 'CEO', 'عميل تجريبي', 'Placeholder client', 'فريق ماركتنج هاوس فهم البيزنس بتاعنا من أول اجتماع. المبيعات زادت بشكل واضح في أول ٣ شهور.', 'The Marketing House team understood our business from the first meeting. Sales grew noticeably within three months.', 5, true, 0),
  ('89a56a5a-baad-43f0-a2a9-62fe938d6c24', 'منى عادل', 'Mona Adel', 'مديرة التسويق', 'Marketing Manager', 'عميل تجريبي', 'Placeholder client', 'الهوية الجديدة غيرت نظرة العملاء لينا تماماً. شغل محترف ومواعيد مظبوطة.', 'The new identity completely changed how customers see us. Professional work, always on time.', 5, true, 1),
  ('eec6bddb-3807-41e9-a18a-d9ef0d875166', 'كريم فؤاد', 'Karim Fouad', 'صاحب مشروع', 'Founder', 'عميل تجريبي', 'Placeholder client', 'أول مرة أشوف تقارير إعلانات واضحة كده. كل جنيه عارف راح فين وجاب إيه.', 'First time I''ve seen ad reports this clear. I know where every pound went and what it brought back.', 5, true, 2),
  ('966625aa-3af1-4fbd-ab6b-2ebb96854a97', 'سارة حسن', 'Sara Hassan', 'مديرة العمليات', 'Operations Director', 'عميل تجريبي', 'Placeholder client', 'الموقع الجديد خفف الضغط على فريقنا والحجوزات الأونلاين بقت أغلب الشغل.', 'The new site took pressure off our team — online bookings are now most of our volume.', 5, true, 3)
